package remilia

import (
	"testing"

	"github.com/KomeiDiSanXian/remilia/openapi/dto"
)

// TestSimpleHandlerExecution 简单测试 Handler 是否执行
func TestSimpleHandlerExecution(t *testing.T) {
	engine := NewEngine()

	executed := false
	engine.OnC2C().HandleE(func(ctx *Context) error {
		executed = true
		return nil
	})

	event := &dto.Payload{
		Type: dto.C2CMessageCreate,
		ID:   "test-1",
	}
	ctx := NewContext(event, nil)
	engine.ProcessEvent(ctx)
	ctx.Release()

	if !executed {
		t.Error("Handler was not executed")
	}
}
